import{_ as e,a as s}from"./chunks/home-assistant-bridge-stopped.CBPfnOza.js";import{_ as n,o,c as a,a2 as r}from"./chunks/framework.Desnpdez.js";const b=JSON.parse('{"title":"Home","description":"","frontmatter":{},"headers":[],"relativePath":"everyday/home.md","filePath":"everyday/home.md"}'),i={name:"everyday/home.md"};function h(l,t,g,p,d,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h1><p><strong>Home</strong> is where you turn the <strong>assistant bridge</strong> on or off and where you copy <strong>links</strong> for other apps.</p><h2 id="what-the-subtitle-means" tabindex="-1">What the subtitle means <a class="header-anchor" href="#what-the-subtitle-means" aria-label="Permalink to &quot;What the subtitle means&quot;">​</a></h2><blockquote><p>Turn on the assistant bridge, then use your connections in ChatGPT, MBIT Chat, or other assistants.</p></blockquote><p>The bridge is a small local service. When it runs, your <strong>enabled</strong> connections each get a stable URL on this computer (by default on port <strong>8000</strong>).</p><h2 id="status-strip-three-steps" tabindex="-1">Status strip (three steps) <a class="header-anchor" href="#status-strip-three-steps" aria-label="Permalink to &quot;Status strip (three steps)&quot;">​</a></h2><p>Read the strip from left to right:</p><table tabindex="0"><thead><tr><th>Step</th><th>Plain meaning</th></tr></thead><tbody><tr><td><strong>Built-in engine</strong></td><td>The packaged runtime is available.</td></tr><tr><td><strong>Bridge</strong></td><td>The assistant bridge is stopped, starting, or running.</td></tr><tr><td><strong>Connections</strong></td><td>How many connections are switched on versus how many you have saved.</td></tr></tbody></table><p><img src="'+e+'" alt="Home — status strip (built-in engine, bridge, connections) and assistant bridge card"></p><p>The pill in the top-right corner summarises the same story (<strong>Stopped</strong>, <strong>Running</strong>, and so on). The <strong>Assistant bridge</strong> card sits directly under the strip in this view: use <strong>Turn on</strong> / <strong>Turn off</strong> there, and <strong>Apply changes</strong> after you edited connections (it restarts the bridge so new settings apply).</p><h2 id="before-you-start-first-time-hints" tabindex="-1">Before you start (first-time hints) <a class="header-anchor" href="#before-you-start-first-time-hints" aria-label="Permalink to &quot;Before you start (first-time hints)&quot;">​</a></h2><p>If the engine is missing or a port is busy, you may see a short <strong>Before you start</strong> checklist on <strong>Home</strong> with items such as the built-in engine and port availability. Expand <strong>Details for troubleshooting</strong> if the app is still working through a problem. (That checklist is not shown in the screenshot above—open the app after a fresh install to see it when prerequisites fail.)</p><h2 id="links-for-other-apps" tabindex="-1">Links for other apps <a class="header-anchor" href="#links-for-other-apps" aria-label="Permalink to &quot;Links for other apps&quot;">​</a></h2><p>Once the bridge has run at least once, you get a table of <strong>enabled</strong> connections.</p><ul><li><strong>Copy link</strong> — paste into the assistant.</li><li><strong>Reference</strong> — optional technical page.</li></ul><p><img src="'+s+'" alt="Home — links for enabled connections while the bridge is running"></p><p>If nothing appears here, open <strong>Connections</strong> and make sure at least one connection is <strong>enabled</strong>, then use <strong>Apply changes</strong> on Home.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><strong><a href="./connections.html">Connections</a></strong> — Library and My connections.</li><li><strong><a href="./settings.html">Settings</a></strong> — change the HTTP port or advanced options.</li><li><strong><a href="./mbit-chat.html">MBIT Chat</a></strong> — automatic sync instead of manual links.</li></ul>',19)])])}const f=n(i,[["render",h]]);export{b as __pageData,f as default};
